api.look('noir');
const cx = api.w/2, cy = 330;
const k = api.seg(t, 0, 1.2);
api.rect(cx-150, cy-70, 300, 150, {r:14, c:'fg', w:4, fill:'panel', k});
api.rect(cx-110, cy-95, 50, 26, {r:4, c:'fg', w:4, k:api.seg(t,0.6,1.2)});
api.rect(cx+60, cy-95, 50, 26, {r:4, c:'fg', w:4, k:api.seg(t,0.6,1.2)});
api.text('+', cx-85, cy-70, {size:28, c:'bad', align:'center', k:api.seg(t,1,1.5)});
api.text('−', cx+85, cy-70, {size:28, c:'a2', align:'center', k:api.seg(t,1,1.5)});
api.shape('battery', cx, cy+5, 120, {c:'bad', w:4, k:api.seg(t,0.4,1.4)});
api.progress(cx-100, cy+120, 200, 18, 0.03, {k:api.seg(t,1.2,2)});
api.text('0%', cx, cy+170, {size:34, c:'bad', align:'center', weight:700, k:api.seg(t,1.4,2.2)});
api.say('Dead battery. Stay calm.', 0.3, 3.3);

api.look('noir');
const W = api.w, cy = 360;
const cam = api.lerp(0, 1, api.ease(api.seg(t,3.5,6)));
api.cam(0, 0, 1 + 0.0*cam);
const car = (x, y, col, label, k) => {
  api.path('M-100 20 L-100 -5 L-70 -10 L-45 -45 L35 -45 L65 -10 L100 -5 L100 20 Z', {x, y, s:1.0, c:col, w:4, fill:'panel', k});
  api.circle(x-60, y+22, 18, {c:'fg', w:4, k});
  api.circle(x+60, y+22, 18, {c:'fg', w:4, k});
  api.text(label, x, y+75, {size:20, c:col, align:'center', weight:700, k});
};
const k1 = api.seg(t,0,1.2), k2 = api.seg(t,0.6,1.8);
car(120, cy-120, 'bad', 'Dead', k1);
car(W-120, cy-120, 'good', 'Good', k2);
api.callout('Park nose to nose', W/2, cy-100, W/2-40, cy+110, {k:api.seg(t,2,3.2), maxw:200});
api.arrow(W/2-30, cy-60, W/2+30, cy-60, {head:true, c:'accent', k:api.seg(t,2,3)});
api.text('Both engines OFF', W/2, cy+190, {size:26, c:'warn', align:'center', weight:700, k:api.seg(t,3.5,4.5)});
api.shape('lock', W/2, cy+260, 50, {c:'warn', w:4, k:api.seg(t,4,5)});
api.say('Park close. Turn both off.', 0.3, 5.5);

api.look('noir');
const cx = api.w/2;
const bat = (x, y, col, name, k) => {
  api.rect(x-70, y-30, 140, 80, {r:10, c:col, w:4, fill:'panel', k});
  api.rect(x-50, y-48, 34, 18, {r:3, c:'fg', w:4, k});
  api.rect(x+16, y-48, 34, 18, {r:3, c:'fg', w:4, k});
  api.text('+', x-33, y-5, {size:26, c:'bad', align:'center', k});
  api.text('−', x+33, y-5, {size:26, c:'a2', align:'center', k});
  api.text(name, x, y+80, {size:20, c:col, align:'center', weight:700, k});
};
const yD = 230, yG = 560;
bat(cx, yD, 'bad', 'Dead', api.seg(t,0,0.8));
bat(cx, yG, 'good', 'Good', api.seg(t,0,0.8));
// clamps in order: 1 red dead+, 2 red good+, 3 black good-, 4 black ground
const cols = ['bad','bad','fg','fg'];
const pts = [[cx-33,yD-48],[cx-33,yG-48],[cx+33,yG-48],[cx+130,yD-100]];
const labs = ['Red to dead +','Red to good +','Black to good −','Black to bare metal'];
for (let i=0;i<4;i++){
  const kk = api.seg(t, 1+i*1.4, 1.8+i*1.4);
  api.dot(pts[i][0], pts[i][1], 9, {c: i<2?'bad':'a2', k:kk});
  api.pin(i+1, pts[i][0]-(i==3?-30:40), pts[i][1]-(i==3?0:0), {k:kk});
}
api.curve(cx-33,yD-48, cx-110,(yD+yG)/2, cx-33,yG-48, {c:'bad', w:5, k:api.seg(t,1.4,2.6)});
api.curve(cx+33,yG-48, cx+130,(yD+yG)/2+60, cx+130,yD-100, {c:'a2', w:5, k:api.seg(t,3.4,5)});
api.rect(cx+100, yD-100, 60, 14, {c:'dim', w:3, k:api.seg(t,4.2,5)});
api.text('Not the dead −', cx+150, yD-60, {size:16, c:'warn', align:'center', k:api.seg(t,5,5.8)});
api.scribble(cx+130, yD-95, 45, 20, {c:'good', k:api.seg(t,5.2,6)});
const s = Math.min(3,Math.floor(Math.max(0,t-1)/1.4));
const caps = ['Red to dead plus','Red to good plus','Black to good minus','Black to bare metal'];
api.text(labs[s], cx, api.h-190, {size:22, c:'fg', align:'center', weight:700, k:api.seg(t,1,1.4)});
api.say('Red first, black last, on metal.', 0.3, 6.5);

api.look('noir');
const cx = api.w/2, cy = 380;
const k = api.seg(t,0,1.2);
api.path('M-100 20 L-100 -5 L-70 -10 L-45 -45 L35 -45 L65 -10 L100 -5 L100 20 Z', {x:cx, y:cy, s:1.7, c:'good', w:4, fill:'panel', k});
api.circle(cx-100, cy+40, 30, {c:'fg', w:4, k});
api.circle(cx+100, cy+40, 30, {c:'fg', w:4, k});
const on = api.seg(t,1.5,2.5);
api.glow(cx+170, cy-10, 70*on, {c:'warn'});
api.glow(cx-170, cy-10, 70*on, {c:'warn'});
api.swarm(30, t, {mode:'rise', cx:cx-120, cy:cy+60, rx:20, ry:60, c:'dim', k:api.seg(t,2,3)});
api.shape('bolt', cx, cy-130, 80*api.ease(api.seg(t,1.5,2.4)), {c:'warn', w:4, fill:'warn'});
api.text('Start the good car', cx, cy+190, {size:24, c:'fg', align:'center', weight:700, k:api.seg(t,0.4,1.2)});
api.text('Wait 3 minutes', cx, cy+230, {size:24, c:'a2', align:'center', weight:700, k:api.seg(t,3,3.8)});
api.arc(cx, cy-230, 36, -Math.PI/2, -Math.PI/2+Math.PI*2*api.seg(t,3,5.5), {c:'a2', w:6});
api.focus(cx, cy, api.lerp(1,1.15,api.ease(api.seg(t,0,6))));
api.say('Start the good car. Wait.', 0.3, 5.5);

api.look('noir');
const cx = api.w/2, cy = 330;
api.text('Remove in reverse', cx, 150, {size:34, c:'fg', align:'center', weight:700, k:api.seg(t,0,1)});
const items = [['Black from metal','fg'],['Black from good −','fg'],['Red from good +','bad'],['Red from dead +','bad']];
items.forEach((it,i)=>{
  const k = api.stag(t,i,{gap:1.0,dur:0.7,from:0.8});
  const y = 250 + i*80;
  api.circle(cx-130, y, 24, {c:it[1]==='bad'?'bad':'a2', w:4, fill:it[1]==='bad'?'bad':'a2', k});
  api.text(String(4-i), cx-130, y-2, {size:22, c:'ink', align:'center', weight:700, k});
  api.text(it[0], cx-85, y-2, {size:22, c:'fg', k});
});
api.arrow(cx+150, 250, cx+150, 540, {c:'accent', w:4, head:true, k:api.seg(t,0.8,4.8)});
api.shape('check', cx, 610, 70, {c:'good', w:6, k:api.seg(t,5,6)});
api.say('Remove in reverse. Drive 30 minutes.', 0.3, 6.5);
